//! Explicit isolated benchmark. No account, renderer, or product mutation.
use cas_core::Engine;
use serde_json::{json,Value};
use std::time::Instant;
fn summary(mut rows:Vec<f64>)->Value{rows.sort_by(f64::total_cmp);json!({"samples":rows.len(),"median_ms":rows[rows.len()/2],"p95_ms":rows[rows.len()*95/100],"max_ms":rows[rows.len()-1]})}
fn main(){let mut reports=vec![];for seconds in [0.1,0.8]{let mut engine=Engine::default();let initial=engine.handle(json!({"op":"new_littoral","version":"cas-littoral-v4","company_layout":"multi-company-v1","seed":47,"mode":"defense","ships":[{"id":"IBS-U-USN-FLETCHER","hp":100,"ammo":100}],"roster":["MCP-034","MCP-116","MCP-167","MCP-011","MCP-103"],"unit_condition":[],"transport_preset":"combat","defense":[]}));assert_eq!(initial["ok"],true);assert_eq!(initial["data"]["littoral"]["groups"].as_array().unwrap().len(),21);assert_eq!(initial["data"]["littoral"]["land"]["entities"].as_array().unwrap().iter().filter(|b|b["side"]=="allies").count(),181);let(mut step,mut serialize,mut bytes,mut peak)=(vec![],vec![],0,0);for i in 0..200{let at=Instant::now();let v=engine.handle(json!({"op":"step","seconds":seconds}));let step_ms=at.elapsed().as_secs_f64()*1000.;assert_eq!(v["ok"],true);let at=Instant::now();let output=serde_json::to_vec(&v).unwrap();let json_ms=at.elapsed().as_secs_f64()*1000.;if i>=20{step.push(step_ms);serialize.push(json_ms);}bytes=bytes.max(output.len());peak=peak.max(v["data"]["littoral"]["land"]["entities"].as_array().unwrap().len());}reports.push(json!({"seconds_per_request":seconds,"friendly_initial":181,"companies":21,"peak_all_bodies":peak,"max_response_bytes":bytes,"rust_simulation_plus_public_view":summary(step),"json_serialization_only":summary(serialize)}));}let result=json!({"scope":"release Rust Engine.handle includes actual simulation and public observation construction; serialization measured separately; no pipe, Godot, or GPU included","source":"same frozen product sources as default195322; separate example executable","reports":reports});std::fs::write("artifacts/littoral-v4/multi/rust-performance.json",serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}
